import math
from numbers import Real

def _is_numeric(value):
    return isinstance(value, Real)

def _pearson(x, y):
    n = len(x)
    if n == 0:
        raise ValueError("no data")

    mean_x = math.fsum(x) / n
    mean_y = math.fsum(y) / n

    cov = math.fsum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
    var_x = math.fsum((xi - mean_x) ** 2 for xi in x)
    var_y = math.fsum((yi - mean_y) ** 2 for yi in y)

    denom = math.sqrt(var_x) * math.sqrt(var_y)
    if denom == 0.0:
        return 0.0

    return cov / denom

def most_correlated_columns(data):
    if not data or len(data) < 2:
        raise ValueError("no data or fewer than two columns")

    columns = []
    for name, col in data.items():
        try:
            values = list(col)
        except TypeError:
            raise TypeError(f"column {name!r} is not a list of numbers")

        for value in values:
            if not _is_numeric(value):
                raise TypeError(f"column {name!r} contains non-numeric value: {value!r}")

        columns.append((name, values))

    lengths = {len(values) for _, values in columns}
    if len(lengths) != 1:
        raise ValueError("all columns must have the same length")

    n = lengths.pop()
    if n == 0:
        raise ValueError("no data")

    best_pair = (columns[0][0], columns[1][0])
    best_abs = -1.0

    for i in range(len(columns)):
        name_i, x = columns[i]
        for j in range(i + 1, len(columns)):
            name_j, y = columns[j]

            r = _pearson(x, y)
            abs_r = abs(r)

            if abs_r > best_abs:
                best_abs = abs_r
                best_pair = (name_i, name_j)

    return best_pair
