def _dist2(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def _initial_centers(data, k):
    # Deterministic farthest-first initialization
    centers = [data[0][:]]
    while len(centers) < k:
        best_point = None
        best_d = -1.0
        for p in data:
            d = min(_dist2(p, c) for c in centers)
            if d > best_d or (d == best_d and (best_point is None or p < best_point)):
                best_d = d
                best_point = p
        centers.append(best_point[:])
    return centers


def kmeans_centers(points, n_clusters):
    # Validate n_clusters
    if isinstance(n_clusters, bool):
        raise ValueError("n_clusters must be a positive integer")
    try:
        k = int(n_clusters)
    except (TypeError, ValueError, OverflowError):
        raise ValueError("n_clusters must be a positive integer")
    if k != n_clusters or k <= 0:
        raise ValueError("n_clusters must be a positive integer")

    # Validate points
    if points is None:
        raise ValueError("points must not be empty")
    try:
        points = list(points)
    except TypeError:
        raise ValueError("points must be an iterable of [x, y] pairs")
    if len(points) == 0:
        raise ValueError("points must not be empty")

    pts = []
    for p in points:
        try:
            if len(p) != 2:
                raise ValueError
            pts.append([float(p[0]), float(p[1])])
        except (TypeError, ValueError, IndexError):
            raise ValueError("each point must be an [x, y] pair")

    n = len(pts)
    if k > n:
        raise ValueError("n_clusters cannot exceed the number of points")

    # If every point is its own cluster, the centers are the points themselves
    if k == n:
        return sorted([p[:] for p in pts])

    data = sorted(pts)
    centers = _initial_centers(data, k)
    assignments = None

    # Lloyd's algorithm
    for _ in range(300):
        new_assignments = []
        assigned_dists = []

        for p in data:
            best_idx = 0
            best_d = _dist2(p, centers[0])
            for i in range(1, k):
                d = _dist2(p, centers[i])
                if d < best_d:
                    best_d = d
                    best_idx = i
            new_assignments.append(best_idx)
            assigned_dists.append(best_d)

        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k
        for p, idx in zip(data, new_assignments):
            sums[idx][0] += p[0]
            sums[idx][1] += p[1]
            counts[idx] += 1

        new_centers = [None] * k
        for i in range(k):
            if counts[i] > 0:
                new_centers[i] = [sums[i][0] / counts[i], sums[i][1] / counts[i]]
            else:
                new_centers[i] = centers[i][:]

        # Reinitialize any empty cluster to a far-away point
        empty = [i for i in range(k) if counts[i] == 0]
        if empty:
            order = sorted(range(n), key=lambda j: (-assigned_dists[j], data[j][0], data[j][1]))
            used = set()
            for i in empty:
                chosen = None
                for j in order:
                    if j not in used:
                        chosen = j
                        break
                if chosen is not None:
                    used.add(chosen)
                    new_centers[i] = data[chosen][:]

        max_shift = max(_dist2(new_centers[i], centers[i]) for i in range(k))

        if assignments is not None and new_assignments == assignments and max_shift < 1e-12:
            centers = new_centers
            break

        assignments = new_assignments
        centers = new_centers

    return sorted([[float(c[0]), float(c[1])] for c in centers])
