def _solve(A, b):
    """Solve A x = b using Gauss-Jordan elimination.

    If the system is singular, free variables are set to 0.
    """
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    scale = max((abs(M[i][j]) for i in range(n) for j in range(n)), default=0.0)
    tol = 1e-12 * max(scale, 1e-300)

    pivot_cols = []
    row = 0

    for col in range(n):
        if row >= n:
            break

        pivot = max(range(row, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) <= tol:
            continue

        if pivot != row:
            M[row], M[pivot] = M[pivot], M[row]

        pivot_val = M[row][col]
        for j in range(col, n + 1):
            M[row][j] /= pivot_val

        for r in range(n):
            if r != row:
                factor = M[r][col]
                if factor != 0.0:
                    for j in range(col, n + 1):
                        M[r][j] -= factor * M[row][j]

        pivot_cols.append(col)
        row += 1

    x = [0.0] * n
    for i, col in enumerate(pivot_cols):
        x[col] = M[i][n]
    return x


def fit_linear_regression(features, values):
    """
    Fits ordinary least-squares linear regression with an intercept.

    Returns:
        dict with 'coefficients' (list of fitted feature coefficients)
        and 'intercept' (fitted intercept).
    """
    n = len(features)
    if n == 0 or len(values) != n:
        raise ValueError("features and values must be non-empty and have the same length")

    p = len(features[0])
    X = [[float(x) for x in row] for row in features]
    y = [float(v) for v in values]

    if any(len(row) != p for row in X):
        raise ValueError("all feature rows must have the same length")

    if p == 0:
        return {"coefficients": [], "intercept": sum(y) / n}

    mean_x = [sum(row[j] for row in X) / n for j in range(p)]
    mean_y = sum(y) / n

    # Build centered normal equations: (Xc^T Xc) * coef = Xc^T yc
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for i in range(n):
        xi = [X[i][j] - mean_x[j] for j in range(p)]
        yi = y[i] - mean_y

        for j in range(p):
            b[j] += xi[j] * yi
            for k in range(j, p):
                A[j][k] += xi[j] * xi[k]

    for j in range(p):
        for k in range(j):
            A[j][k] = A[k][j]

    coefficients = _solve(A, b)
    intercept = mean_y - sum(coefficients[j] * mean_x[j] for j in range(p))

    return {"coefficients": coefficients, "intercept": float(intercept)}
