import math

def column_correlation_matrix(data, cols):
    n = len(data)
    m = len(cols)

    if n == 0:
        return []

    # Extract columns by index
    columns = [[row[j] for row in data] for j in range(m)]

    # Center each column around its mean
    means = [sum(col) / n for col in columns]
    centered = [[x - mean for x in col] for col, mean in zip(columns, means)]

    # Sum of squared deviations for each column
    ss = [sum(x * x for x in col) for col in centered]

    matrix = [[0.0] * m for _ in range(m)]

    for i in range(m):
        for j in range(m):
            if i == j:
                matrix[i][j] = 1.0
            else:
                denom = math.sqrt(ss[i] * ss[j])
                if denom == 0.0:
                    # Pearson correlation is undefined for a constant column;
                    # returning 0.0 for off-diagonal entries.
                    matrix[i][j] = 0.0
                else:
                    cross = sum(centered[i][k] * centered[j][k] for k in range(n))
                    matrix[i][j] = cross / denom

    return matrix
