import csv
import io
import re

_NUMERIC_RE = re.compile(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?')

def _convert_cell(value):
    """Convert empty/missing cells to None, numeric-looking strings to numbers."""
    if value is None or value == "":
        return None

    stripped = value.strip()
    if _NUMERIC_RE.fullmatch(stripped):
        try:
            return int(stripped)
        except ValueError:
            try:
                return float(stripped)
            except (ValueError, OverflowError):
                return value
    return value

def merge_csv_texts(csv_texts):
    if not csv_texts:
        return []

    all_columns = []
    seen = set()
    parsed = []

    # First pass: parse each CSV and collect the unified column list.
    for text in csv_texts:
        reader = csv.reader(io.StringIO(text, newline=''))
        try:
            header = next(reader)
        except StopIteration:
            parsed.append(([], []))
            continue

        for col in header:
            if col not in seen:
                seen.add(col)
                all_columns.append(col)

        parsed.append((header, list(reader)))

    # Second pass: build one dict per data row.
    result = []
    for header, rows in parsed:
        for raw_row in rows:
            row = {col: None for col in all_columns}
            for i, col in enumerate(header):
                if i < len(raw_row):
                    row[col] = _convert_cell(raw_row[i])
                else:
                    row[col] = None
            result.append(row)

    return result
