from collections import Counter
import math
from typing import Dict, List, Optional

def letter_count_correlations(strings: List[str]) -> Optional[Dict[str, Dict[str, float]]]:
    if not strings:
        return None

    counters = [Counter(s) for s in strings]
    letters = sorted({ch for counter in counters for ch in counter})

    if not letters:
        return {}

    n = len(strings)
    counts = {ch: [counter[ch] for counter in counters] for ch in letters}

    centered = {}
    variances = {}

    for ch in letters:
        vals = counts[ch]
        mean = sum(vals) / n
        centered_vals = [v - mean for v in vals]
        centered[ch] = centered_vals
        variances[ch] = sum(v * v for v in centered_vals)

    result: Dict[str, Dict[str, float]] = {ch: {} for ch in letters}

    for i, x in enumerate(letters):
        result[x][x] = 1.0
        for y in letters[i + 1:]:
            cov = sum(a * b for a, b in zip(centered[x], centered[y]))
            r = cov / math.sqrt(variances[x] * variances[y])
            result[x][y] = r
            result[y][x] = r

    return result
