import statistics

def standardize_series(x, y, labels):
    def zscore(values):
        n = len(values)
        if n == 0:
            return []
        mean = statistics.mean(values)
        std = statistics.pstdev(values)  # population standard deviation
        if std == 0:
            return [0.0] * n
        return [(v - mean) / std for v in values]

    return {
        label: [zscore(xs), zscore(ys)]
        for xs, ys, label in zip(x, y, labels)
    }
