import csv
from io import StringIO

def normalize_numeric_columns(csv_text):
    rows = list(csv.reader(StringIO(csv_text)))
    if not rows:
        raise ValueError("no numeric columns")

    header = rows[0]
    data = [row for row in rows[1:] if row]  # skip blank lines
    if not data:
        raise ValueError("no numeric columns")

    # Build columns in header order.
    columns = [
        [row[i] if i < len(row) else "" for row in data]
        for i in range(len(header))
    ]

    result = {name: col for name, col in zip(header, columns)}

    # Detect numeric columns: all values must parse as float.
    numeric_cols = []
    for name, values in result.items():
        try:
            nums = [float(v) for v in values]
        except (TypeError, ValueError):
            continue
        numeric_cols.append((name, nums))

    if not numeric_cols:
        raise ValueError("no numeric columns")

    # Min-max scale numeric columns.
    for name, nums in numeric_cols:
        low, high = min(nums), max(nums)
        if low == high:
            result[name] = [0.0] * len(nums)
        else:
            span = high - low
            result[name] = [(x - low) / span for x in nums]

    return result
