import math

def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("input must not be empty")

    for row in array:
        if len(row) != 5:
            raise ValueError("each row must have exactly 5 values")

    n = len(array)
    columns = list(zip(*array))
    means = [sum(col) / n for col in columns]

    centered = [[x - mean for x in col] for col, mean in zip(columns, means)]
    sum_sq = [sum(x * x for x in col) for col in centered]

    result = [[1.0 if i == j else 0.0 for j in range(5)] for i in range(5)]

    for i in range(5):
        for j in range(i + 1, 5):
            denom = math.sqrt(sum_sq[i] * sum_sq[j])
            if denom == 0.0:
                corr = float("nan")
            else:
                corr = sum(centered[i][k] * centered[j][k] for k in range(n)) / denom
            result[i][j] = corr
            result[j][i] = corr

    return result
