from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "basefont", "bgsound", "br", "col", "embed", "frame",
    "hr", "img", "input", "keygen", "link", "meta", "param", "source",
    "track", "wbr"
}

class _FirstTagTextParser(HTMLParser):
    def __init__(self, target):
        super().__init__(convert_charrefs=True)
        self.target = target.lower()
        self.stack = []
        self.capturing = False
        self.done = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        tag = tag.lower()
        if tag in _VOID_TAGS:
            return

        if not self.capturing and tag == self.target:
            self.capturing = True

        self.stack.append(tag)

    def handle_endtag(self, tag):
        if self.done:
            return
        tag = tag.lower()
        if tag in _VOID_TAGS:
            return

        if tag in self.stack:
            while self.stack and self.stack[-1] != tag:
                self.stack.pop()
            if self.stack:
                self.stack.pop()

            if self.capturing and self.target not in self.stack:
                self.capturing = False
                self.done = True

    def handle_data(self, data):
        if self.capturing and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    """
    Return the text content of the first element with the given tag name.
    Returns None if no such element exists or its text content is empty.
    """
    if not isinstance(html, str) or not isinstance(tag, str):
        return None

    tag = tag.strip().lower()

    # Void elements cannot contain text content.
    if tag in _VOID_TAGS:
        return None

    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    text = "".join(parser.parts)
    return text or None
```

