import csv
import io
import re
from datetime import datetime

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")

def _parse_iso_date(value):
    """Parse a strict YYYY-MM-DD string into a date, raising ValueError if invalid."""
    if not isinstance(value, str) or _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"Invalid date: {value!r}; expected YYYY-MM-DD")
    try:
        return datetime.strptime(value, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError(f"Invalid date: {value!r}") from exc

def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    start = _parse_iso_date(start_date)
    end = _parse_iso_date(end_date)

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV input must contain a header row")

    if column_name not in header:
        raise ValueError(f"Column {column_name!r} not found in header")

    date_idx = header.index(column_name)
    result = []

    for row in reader:
        if len(row) <= date_idx:
            continue

        try:
            row_date = _parse_iso_date(row[date_idx])
        except ValueError:
            continue

        if start <= row_date <= end:
            result.append(row)

    return result
