import csv
import io
import math


def _read_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    try:
        rows = list(reader)
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from None

    if not rows:
        raise ValueError("CSV text is empty")

    header = [h.strip() for h in rows[0]]
    return header, rows[1:]


def _cell(row, idx):
    return row[idx] if idx < len(row) else ""


def _parse_float(value, context):
    s = value.strip() if value is not None else ""
    if s == "":
        raise ValueError(f"missing value in {context}")

    try:
        f = float(s)
    except (TypeError, ValueError):
        raise ValueError(f"non-numeric value {value!r} in {context}") from None

    if not math.isfinite(f):
        raise ValueError(f"non-finite value {value!r} in {context}")

    return f


def _solve_linear_system(A, b):
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("singular matrix in linear regression")

        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pv = M[col][col]
        M[col] = [v / pv for v in M[col]]

        for r in range(n):
            if r != col:
                factor = M[r][col]
                if factor != 0.0:
                    row_r = M[r]
                    row_c = M[col]
                    for c in range(n + 1):
                        row_r[c] -= factor * row_c[c]

    return [M[i][n] for i in range(n)]


def _fit_ols(X, y):
    m = len(X[0])
    A = [[0.0] * m for _ in range(m)]
    b = [0.0] * m

    for row, y_val in zip(X, y):
        for i in range(m):
            xi = row[i]
            if xi != 0.0:
                b[i] += xi * y_val
                Ai = A[i]
                for j in range(m):
                    Ai[j] += xi * row[j]

    return _solve_linear_system(A, b)


def predict_linear_regression(train_csv, test_csv, target):
    target = target.strip()

    train_header, train_rows = _read_csv(train_csv)
    if target not in train_header:
        raise ValueError(f"target column {target!r} not found in training CSV")

    feature_names = [h for h in train_header if h != target]
    feature_indices = [i for i, h in enumerate(train_header) if h != target]
    target_idx = train_header.index(target)

    X = []
    y = []

    for row in train_rows:
        features = [
            _parse_float(_cell(row, idx), "training feature")
            for idx in feature_indices
        ]
        y_val = _parse_float(_cell(row, target_idx), "training target")
        X.append([1.0] + features)
        y.append(y_val)

    if not X:
        raise ValueError("training CSV has no data rows")

    beta = _fit_ols(X, y)

    test_header, test_rows = _read_csv(test_csv)
    test_indices = []

    for name in feature_names:
        if name not in test_header:
            raise ValueError(f"feature column {name!r} not found in test CSV")
        test_indices.append(test_header.index(name))

    predictions = []

    for row in test_rows:
        features = [
            _parse_float(_cell(row, idx), "test feature")
            for idx in test_indices
        ]
        x_row = [1.0] + features
        pred = sum(coef * value for coef, value in zip(beta, x_row))
        predictions.append(float(pred))

    return predictions
```

