import csv
import io

def normalize_csv_columns(csv_text):
    """
    Parse CSV text with a header row and numeric data, then min-max normalize
    each column to the range [0, 1]. Constant columns become all zeros.
    """
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {}

    # Remove a UTF-8 BOM from the first header name, if present
    if header and header[0].startswith('\ufeff'):
        header[0] = header[0][1:]

    columns = {name: [] for name in header}

    for row in reader:
        if not row:  # skip blank lines
            continue
        for name, cell in zip(header, row):
            columns[name].append(float(cell))

    normalized = {}

    for name, values in columns.items():
        if not values:
            normalized[name] = []
            continue

        low = min(values)
        high = max(values)

        if high == low:
            normalized[name] = [0.0] * len(values)
        else:
            span = high - low
            normalized[name] = [(v - low) / span for v in values]

    return normalized
```

