import math

def standardize_columns(data):
    result = {}

    for col, values in data.items():
        if not values:
            result[col] = []
            continue

        present = [x for x in values if x is not None]
        if not present:
            raise ValueError(f"Column {col!r} has no non-None values")

        mean = sum(present) / len(present)
        filled = [mean if x is None else x for x in values]

        # Population standard deviation: divide by n
        variance = sum((x - mean) ** 2 for x in filled) / len(filled)
        std = math.sqrt(variance)

        if std == 0.0:
            result[col] = [0.0 for _ in filled]
        else:
            result[col] = [(x - mean) / std for x in filled]

    return result
