from html.parser import HTMLParser
from typing import List


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.table_depth = 0
        self.target_depth = None
        self.found = False
        self.finished = False
        self.nested_count = 0
        self.rows: List[List[str]] = []
        self.current_row = None
        self.current_cell = None

    @staticmethod
    def _is_data_table(attrs):
        for name, value in attrs:
            if name == "class":
                return value == "data-table"
        return False

    def _target_active(self):
        return self.target_depth is not None and not self.finished

    def _rows_active(self):
        return self._target_active() and self.nested_count == 0

    def _close_cell(self):
        if self.current_cell is not None and self.current_row is not None:
            self.current_row[-1] = "".join(self.current_cell)
            self.current_cell = None

    def _close_row(self):
        if self.current_row is not None:
            self._close_cell()
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        if self.finished:
            return

        if tag == "table":
            self.table_depth += 1

            if self.target_depth is None and not self.found:
                if self._is_data_table(attrs):
                    self.found = True
                    self.target_depth = self.table_depth
                    self.rows = []
                    self.current_row = None
                    self.current_cell = None
            elif self.target_depth is not None and self.table_depth > self.target_depth:
                self.nested_count += 1

        elif tag == "tr":
            if self._rows_active():
                if self.current_row is not None:
                    self._close_row()
                self.current_row = []
                self.rows.append(self.current_row)

        elif tag == "td":
            if self._rows_active() and self.current_row is not None:
                if self.current_cell is not None:
                    self._close_cell()
                self.current_cell = []
                self.current_row.append(self.current_cell)

    def handle_endtag(self, tag):
        if self.finished:
            return

        if tag == "table":
            if self.target_depth is not None:
                if self.table_depth == self.target_depth:
                    self._close_cell()
                    self._close_row()
                    self.finished = True
                elif self.table_depth > self.target_depth:
                    if self.nested_count > 0:
                        self.nested_count -= 1
            self.table_depth -= 1

        elif tag == "tr":
            if self._rows_active() and self.current_row is not None:
                self._close_row()

        elif tag == "td":
            if self._rows_active() and self.current_cell is not None:
                self._close_cell()

    def handle_data(self, data):
        if self.finished:
            return
        if self.current_cell is not None and self.target_depth is not None:
            self.current_cell.append(data)

    def finalize(self):
        if not self.finished:
            self._close_cell()
            self._close_row()


def extract_data_table_rows(html: str) -> List[List[str]]:
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    parser.finalize()
    return parser.rows
```

