def _solve_linear_system(A, b):
    """Solve A x = b using Gauss-Jordan elimination with partial pivoting."""
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot_row = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot_row][col]) < 1e-12:
            raise ValueError("singular matrix")
        if pivot_row != col:
            M[col], M[pivot_row] = M[pivot_row], M[col]

        pivot = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pivot

        for r in range(n):
            if r == col:
                continue
            factor = M[r][col]
            if factor != 0.0:
                for j in range(col, n + 1):
                    M[r][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]


def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    if len(train_X) == 0:
        raise ValueError("training set is empty")
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y must have the same length")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y must have the same length")
    if len(test_X) == 0:
        raise ValueError("test set is empty")

    # Design matrix with intercept column
    X = [[1.0] + [float(v) for v in row] for row in train_X]
    y = [float(v) for v in train_y]

    n = len(X)
    p = len(X[0])

    # Normal equations: X^T X beta = X^T y
    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p

    for i in range(n):
        xi = X[i]
        yi = y[i]
        for a in range(p):
            Xty[a] += xi[a] * yi
            for b in range(p):
                XtX[a][b] += xi[a] * xi[b]

    beta = _solve_linear_system(XtX, Xty)

    # R^2 on test data
    test_y_vals = [float(v) for v in test_y]
    mean_y = sum(test_y_vals) / len(test_y_vals)

    ss_res = 0.0
    ss_tot = 0.0

    for row, actual in zip(test_X, test_y_vals):
        pred = beta[0]
        for j, val in enumerate(row):
            pred += beta[j + 1] * float(val)

        diff = actual - pred
        ss_res += diff * diff

        diff_mean = actual - mean_y
        ss_tot += diff_mean * diff_mean

    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0

    return float(1.0 - ss_res / ss_tot)
```

