def standardize_columns(rows, columns):
    n = len(rows)
    if n == 0:
        return {name: [] for name in columns}

    result = {}

    for name, values in zip(columns, zip(*rows)):
        vals = list(values)

        # Constant column (or a single row) -> all zeros
        if min(vals) == max(vals):
            result[name] = [0.0] * n
            continue

        mean = sum(vals) / n
        variance = sum((x - mean) ** 2 for x in vals) / n  # population variance
        std = variance ** 0.5

        if std == 0.0:
            result[name] = [0.0] * n
        else:
            result[name] = [(x - mean) / std for x in vals]

    return result
