def merge_and_standardize(rows1, rows2):
    # Collect feature column names, preserving first-seen order.
    cols1 = []
    for row in rows1:
        for key in row:
            if key != 'id' and key not in cols1:
                cols1.append(key)

    cols2 = []
    for row in rows2:
        for key in row:
            if key != 'id' and key not in cols2:
                cols2.append(key)

    # Compute population mean/std for each first-table feature column,
    # ignoring missing (None) values.
    stats = {}
    for col in cols1:
        vals = [row[col] for row in rows1 if row.get(col) is not None]
        if vals:
            mean = sum(vals) / len(vals)
            var = sum((v - mean) ** 2 for v in vals) / len(vals)
            std = var ** 0.5
        else:
            mean = None
            std = None
        stats[col] = (mean, std)

    def std_value(value, col):
        if value is None:
            return None
        mean, std = stats[col]
        if std is None or std == 0:
            return 0.0
        return (value - mean) / std

    # Group rows by id to implement an outer join.
    groups1 = {}
    for row in rows1:
        groups1.setdefault(row['id'], []).append(row)

    groups2 = {}
    for row in rows2:
        groups2.setdefault(row['id'], []).append(row)

    result = []
    for id_ in sorted(set(groups1) | set(groups2)):
        g1 = groups1.get(id_, [])
        g2 = groups2.get(id_, [])

        if g1 and g2:
            pairs = [(r1, r2) for r1 in g1 for r2 in g2]
        elif g1:
            pairs = [(r1, None) for r1 in g1]
        else:
            pairs = [(None, r2) for r2 in g2]

        for r1, r2 in pairs:
            merged = {'id': id_}

            for col in cols1:
                merged[col] = std_value(r1.get(col) if r1 is not None else None, col)

            for col in cols2:
                merged[col] = r2.get(col) if r2 is not None else None

            result.append(merged)

    return result
