import math

def standardize_columns(rows):
    if not rows:
        raise ValueError("rows must not be empty")

    n = len(rows)
    ncols = len(rows[0])
    result = [list(row) for row in rows]

    for j in range(ncols):
        col = [float(row[j]) for row in rows]

        # A column with all equal values becomes all zeros.
        if all(x == col[0] for x in col):
            for i in range(n):
                result[i][j] = 0.0
            continue

        mean = sum(col) / n
        variance = sum((x - mean) ** 2 for x in col) / n
        std = math.sqrt(variance)

        if std == 0.0:
            for i in range(n):
                result[i][j] = 0.0
        else:
            for i in range(n):
                result[i][j] = (col[i] - mean) / std

    return result
