def seasonal_decomposition(values, period, model):
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or period <= 0:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)

    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    half = period // 2
    trend = [None] * n

    # Centered moving average trend
    for i in range(half, n - half):
        window = values[i - half: i + half + 1]
        if period % 2 == 0:
            # 2 x period centered MA: half-weight the endpoints
            trend[i] = (0.5 * window[0] + sum(window[1:-1]) + 0.5 * window[-1]) / period
        else:
            trend[i] = sum(window) / period

    # Detrended values grouped by seasonal phase
    buckets = [[] for _ in range(period)]
    for i in range(half, n - half):
        if model == 'additive':
            detrended = values[i] - trend[i]
        else:
            if trend[i] == 0:
                raise ValueError("multiplicative decomposition requires non-zero trend values")
            detrended = values[i] / trend[i]
        buckets[i % period].append(detrended)

    if any(len(b) == 0 for b in buckets):
        raise ValueError("not enough data to estimate all seasonal phases")

    # Average seasonal index per phase, then normalise
    phase_means = [sum(b) / len(b) for b in buckets]
    norm = sum(phase_means) / period

    if model == 'additive':
        seasonal_indices = [m - norm for m in phase_means]
    else:
        if norm == 0:
            raise ValueError("cannot normalise multiplicative seasonal indices to average 1")
        seasonal_indices = [m / norm for m in phase_means]

    seasonal = [seasonal_indices[i % period] for i in range(n)]

    # Residuals only where trend is defined
    residual = [None] * n
    for i in range(half, n - half):
        if model == 'additive':
            residual[i] = values[i] - trend[i] - seasonal[i]
        else:
            denom = trend[i] * seasonal[i]
            if denom == 0:
                raise ValueError("multiplicative decomposition has zero denominator")
            residual[i] = values[i] / denom

    return {'trend': trend, 'seasonal': seasonal, 'residual': residual}
