def scale_table_columns(data):
    if not data:
        return {}

    columns = list(data.keys())
    n = len(next(iter(data.values())))

    # Keep only rows where no column has None
    keep_rows = [
        i for i in range(n)
        if all(data[col][i] is not None for col in columns)
    ]

    result = {}

    for col in columns:
        values = [data[col][i] for i in keep_rows]

        if not values:
            result[col] = []
            continue

        lo = min(values)
        hi = max(values)

        if lo == hi:
            result[col] = [0.0] * len(values)
        else:
            span = hi - lo
            result[col] = [(v - lo) / span for v in values]

    return result
```

