def _solve_linear_system(A, b):
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("singular matrix")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for r in range(col + 1, n):
            factor = M[r][col] / pivot_val
            if factor != 0.0:
                for c in range(col, n + 1):
                    M[r][c] -= factor * M[col][c]

    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n]
        for j in range(i + 1, n):
            s -= M[i][j] * x[j]
        x[i] = s / M[i][i]

    return x


def column_linear_regression(rows, columns, target):
    if not rows:
        raise ValueError("rows is empty")
    if target not in columns:
        raise ValueError("target is not one of the columns")

    target_idx = columns.index(target)
    pred_indices = [i for i in range(len(columns)) if i != target_idx]

    # Normal equations: X^T X beta = X^T y, with intercept as first column
    k = len(pred_indices) + 1
    xtx = [[0.0] * k for _ in range(k)]
    xty = [0.0] * k

    for row in rows:
        y = row[target_idx]
        x = [1.0] + [row[i] for i in pred_indices]

        for i in range(k):
            xi = x[i]
            xty[i] += xi * y
            for j in range(k):
                xtx[i][j] += xi * x[j]

    beta = _solve_linear_system(xtx, xty)
    return beta[1:], beta[0]
