import math

def standardize_numeric_columns(data):
    result = {}

    for col, values in data.items():
        # Try to convert the whole column to floats.
        try:
            nums = [float(v) for v in values]
        except (TypeError, ValueError, OverflowError):
            result[col] = values          # non-numeric column: unchanged
            continue

        n = len(nums)
        if n == 0:
            result[col] = values
            continue

        # Constant column becomes all zeros.
        if all(x == nums[0] for x in nums):
            result[col] = [0.0] * n
            continue

        mean = math.fsum(nums) / n
        variance = math.fsum((x - mean) ** 2 for x in nums) / n
        std = math.sqrt(variance)         # population standard deviation

        if std == 0.0:
            result[col] = [0.0] * n
        else:
            result[col] = [(x - mean) / std for x in nums]

    return result
