from decimal import Decimal

def weather_column_summary(column, data):
    col_index = {
        'Temperature': 1,
        'Humidity': 2,
        'Wind Speed': 3,
        'Precipitation': 4,
    }

    if column not in col_index:
        raise ValueError(f"Unsupported column: {column!r}")

    idx = col_index[column]

    if not data:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10,
        }

    values = [row[idx] for row in data]
    total = sum(values)
    mn = min(values)
    mx = max(values)

    histogram = [0] * 10

    if mn == mx:
        # All values are the same, so they all fall in the last bin.
        histogram[-1] = len(values)
    else:
        mn_d = Decimal(str(mn))
        width_d = (Decimal(str(mx)) - mn_d) / Decimal(10)

        for v in values:
            if v == mx:
                bin_idx = 9
            else:
                bin_idx = int((Decimal(str(v)) - mn_d) / width_d)
                if bin_idx < 0:
                    bin_idx = 0
                elif bin_idx > 9:
                    bin_idx = 9
            histogram[bin_idx] += 1

    return {
        'sum': total,
        'mean': total / len(values),
        'min': mn,
        'max': mx,
        'histogram': histogram,
    }
```

