from collections import defaultdict
from fractions import Fraction

def association_chi_square(left, right):
    # Build id -> list of categories for a relational-style join
    left_by_id = defaultdict(list)
    right_by_id = defaultdict(list)

    for id_, cat in left:
        left_by_id[id_].append(cat)
    for id_, cat in right:
        right_by_id[id_].append(cat)

    # Join on id and count left_category x right_category
    counts = defaultdict(lambda: defaultdict(int))
    n = 0

    for id_, left_cats in left_by_id.items():
        if id_ not in right_by_id:
            continue
        for lcat in left_cats:
            for rcat in right_by_id[id_]:
                counts[lcat][rcat] += 1
                n += 1

    if n == 0:
        return (0.0, 0)

    row_totals = {l: sum(row.values()) for l, row in counts.items()}
    col_totals = defaultdict(int)
    for row in counts.values():
        for r, c in row.items():
            col_totals[r] += c

    left_cats = list(counts.keys())
    right_cats = list(col_totals.keys())

    # Pearson chi-square: sum (O - E)^2 / E
    # E = row_total * col_total / n
    # Use exact rational arithmetic to avoid floating-point drift
    stat = Fraction(0, 1)
    for l in left_cats:
        for r in right_cats:
            observed = counts[l].get(r, 0)
            expected_num = row_totals[l] * col_totals[r]
            stat += Fraction(
                (n * observed - expected_num) ** 2,
                n * expected_num
            )

    dof = (len(left_cats) - 1) * (len(right_cats) - 1)
    return (float(stat), int(dof))
```

