from datetime import datetime
from zoneinfo import ZoneInfo

def publication_hour_stats(articles, timezone):
    if not articles:
        raise ValueError("articles list must not be empty")

    tz = ZoneInfo(timezone)
    hours_by_category = {}

    for article in articles:
        if "category" not in article or "published_time" not in article:
            raise ValueError("each article must have 'category' and 'published_time'")

        published = article["published_time"]

        # Normalize 'Z' to an explicit UTC offset for fromisoformat compatibility
        if published.endswith(("Z", "z")):
            published = published[:-1] + "+00:00"

        dt = datetime.fromisoformat(published)

        if dt.tzinfo is None:
            raise ValueError("published_time must include a UTC offset")

        local_hour = dt.astimezone(tz).hour
        hours_by_category.setdefault(article["category"], []).append(local_hour)

    return {
        category: {
            "count": len(hours),
            "mean": sum(hours) / len(hours),
            "min": min(hours),
            "max": max(hours),
        }
        for category, hours in sorted(hours_by_category.items())
    }
