from math import sqrt

def column_correlations(data):
    columns = list(data)
    stats = {}

    # Precompute centered values and the square root of sum of squared deviations
    for col, values in data.items():
        n = len(values)
        mean = sum(values) / n
        centered = [v - mean for v in values]
        norm = sqrt(sum(v * v for v in centered))
        stats[col] = (centered, norm)

    result = {}
    for x in columns:
        result[x] = {}
        for y in columns:
            if x == y:
                result[x][y] = 1.0
            else:
                cx, nx = stats[x]
                cy, ny = stats[y]

                if nx == 0 or ny == 0:
                    result[x][y] = float('nan')  # undefined for constant columns
                else:
                    numerator = sum(a * b for a, b in zip(cx, cy))
                    result[x][y] = numerator / (nx * ny)

    return result
