import csv
from io import StringIO

def _parse_number(value):
    """Return value as int/float if possible, otherwise None."""
    s = value.strip()
    if not s:
        return None
    try:
        return int(s)
    except ValueError:
        try:
            return float(s)
        except ValueError:
            return None


def sort_csv_rows(csv_text, sort_by_column='title'):
    # Remove UTF-8 BOM if present
    if csv_text.startswith('\ufeff'):
        csv_text = csv_text[1:]

    reader = csv.reader(StringIO(csv_text))
    header = next(reader, None)
    if not header:
        return []

    rows = [row for row in reader if row]  # skip blank lines
    if not rows:
        return []

    # Build list of dicts, padding/truncating rows to match the header
    records = []
    for row in rows:
        row = list(row)
        if len(row) < len(header):
            row += [''] * (len(header) - len(row))
        else:
            row = row[:len(header)]
        records.append(dict(zip(header, row)))

    # Detect columns where every value is numeric
    numeric_cols = set()
    for col in header:
        if all(_parse_number(rec[col]) is not None for rec in records):
            numeric_cols.add(col)

    # Convert numeric columns to numbers
    for rec in records:
        for col in numeric_cols:
            rec[col] = _parse_number(rec[col])

    # Sort; numeric columns sort numerically, others lexicographically
    records.sort(key=lambda rec: rec[sort_by_column])
    return records
