import numbers
from itertools import accumulate

def normalized_cumulative_sums(data):
    if not data:
        raise ValueError("data is empty")

    result = {}

    for name, column in data.items():
        values = list(column)

        if not values:
            raise ValueError("data is empty")

        for value in values:
            if not isinstance(value, numbers.Real):
                raise TypeError(f"non-numeric value in column {name!r}: {value!r}")
            if value != value:  # NaN is the only real number not equal to itself
                raise ValueError(f"NaN in column {name!r}")

        cumulative = list(accumulate(values))
        low = min(cumulative)
        high = max(cumulative)

        if high == low:
            result[name] = [0.0] * len(cumulative)
        else:
            result[name] = [float((x - low) / (high - low)) for x in cumulative]

    return result
