def standardize_by_group(records):
    required_keys = ('id', 'age', 'income')

    # Validate all records first
    for record in records:
        for key in required_keys:
            if key not in record:
                raise ValueError(f"record is missing required key: {key!r}")

    # Group record indices by id
    groups = {}
    for idx, record in enumerate(records):
        groups.setdefault(record['id'], []).append(idx)

    def mean_and_population_std(values):
        n = len(values)
        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n
        return mean, variance ** 0.5

    # Compute mean and population std for each group
    stats = {}
    for group_id, indices in groups.items():
        ages = [records[i]['age'] for i in indices]
        incomes = [records[i]['income'] for i in indices]

        age_mean, age_std = mean_and_population_std(ages)
        income_mean, income_std = mean_and_population_std(incomes)

        stats[group_id] = (age_mean, age_std, income_mean, income_std)

    # Build standardized records in original input order
    result = []
    for record in records:
        group_id = record['id']
        age_mean, age_std, income_mean, income_std = stats[group_id]

        age_z = 0.0 if age_std == 0 else (record['age'] - age_mean) / age_std
        income_z = 0.0 if income_std == 0 else (record['income'] - income_mean) / income_std

        result.append({
            'id': group_id,
            'age': float(age_z),
            'income': float(income_z),
        })

    return result
