import re
import xml.etree.ElementTree as ET

def xml_to_dict(xml):
    # ElementTree rejects str input that contains an encoding declaration,
    # so remove it when the input is already a decoded string.
    if isinstance(xml, str):
        xml = re.sub(
            r'^\s*(<\?xml\s[^>]*?)encoding\s*=\s*["\'][^"\']*["\']',
            r'\1',
            xml,
            count=1,
        )

    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(f"Malformed XML: {exc}") from exc

    return {root.tag: _element_to_value(root)}


def _element_to_value(elem):
    children = list(elem)

    # Leaf element: no attributes and no children -> text or None.
    if not elem.attrib and not children:
        text = (elem.text or "").strip()
        return text if text else None

    result = {}

    # Attributes are prefixed with '@'.
    for attr, value in elem.attrib.items():
        result["@" + attr] = value

    # Child elements keyed by tag; repeated tags become lists.
    for child in children:
        child_value = _element_to_value(child)
        if child.tag in result:
            existing = result[child.tag]
            if isinstance(existing, list):
                existing.append(child_value)
            else:
                result[child.tag] = [existing, child_value]
        else:
            result[child.tag] = child_value

    # Direct text, if any, goes under '#text'.
    text = (elem.text or "").strip()
    if text:
        result["#text"] = text

    return result
