import math

def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    # Step 1: apply replacements to every value in every column
    replaced = {
        col: [replacements.get(value, value) for value in values]
        for col, values in data.items()
    }

    # Step 2: encode any column that contains strings
    encoded = {}
    for col, values in replaced.items():
        if any(isinstance(value, str) for value in values):
            distinct = sorted(set(values), key=lambda x: (str(x), type(x).__name__))
            codes = {value: i for i, value in enumerate(distinct)}
            encoded[col] = [codes[value] for value in values]
        else:
            encoded[col] = list(values)

    # Step 3: standardize each column
    result = {}
    for col, values in encoded.items():
        n = len(values)
        if n == 0:
            result[col] = []
            continue

        mean = sum(values) / n

        if n <= 1:
            result[col] = [0.0] * n
            continue

        sample_variance = sum((x - mean) ** 2 for x in values) / (n - 1)
        sample_std = math.sqrt(sample_variance)

        if sample_std == 0:
            result[col] = [0.0] * n
        else:
            result[col] = [(x - mean) / sample_std for x in values]

    return result
