from math import sqrt

def correlation_without_column(data, column):
    numeric = {}
    for name, values in data.items():
        if name == column:
            continue
        if all(isinstance(v, (int, float)) for v in values):
            numeric[name] = values

    if not numeric:
        return None

    names = list(numeric)
    n = len(next(iter(numeric.values())))
    if n == 0:
        return None

    centered = {}
    norms = {}
    for name in names:
        vals = numeric[name]
        mean = sum(vals) / n
        c = [v - mean for v in vals]
        centered[name] = c
        norms[name] = sum(v * v for v in c)

    def pearson(x, y):
        if norms[x] == 0 or norms[y] == 0:
            return float('nan')
        num = sum(a * b for a, b in zip(centered[x], centered[y]))
        return num / sqrt(norms[x] * norms[y])

    result = {x: {} for x in names}
    for i, x in enumerate(names):
        for y in names[i:]:
            r = pearson(x, y)
            result[x][y] = r
            result[y][x] = r

    return result
