import math
import re
from collections import Counter

def tfidf_scores_for_question_articles(titles, contents):
    selected = [
        body for title, body in zip(titles, contents)
        if 'how' in title.lower() or 'what' in title.lower()
    ]

    if not selected:
        return {}

    docs = [Counter(re.findall(r'\w{2,}', body.lower())) for body in selected]

    n = len(selected)
    df = Counter()
    for doc in docs:
        for word in doc:
            df[word] += 1

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1
        for word in df
    }

    totals = {}
    for doc in docs:
        if not doc:
            continue

        weighted = {word: count * idf[word] for word, count in doc.items()}
        norm = math.sqrt(sum(score * score for score in weighted.values()))

        if norm == 0:
            continue

        for word, score in weighted.items():
            totals[word] = totals.get(word, 0.0) + score / norm

    return {word: totals[word] for word in sorted(totals)}
