def zscores_by_date(rows):
    if not rows:
        return []

    n = len(rows)
    ncols = len(rows[0][1])

    # Column means
    means = [0.0] * ncols
    for _, values in rows:
        for j, v in enumerate(values):
            means[j] += v
    means = [m / n for m in means]

    # Population standard deviation for each column
    stds = [0.0] * ncols
    for j in range(ncols):
        ss = 0.0
        for _, values in rows:
            diff = values[j] - means[j]
            ss += diff * diff
        stds[j] = (ss / n) ** 0.5

    # Compute z-scores
    result = []
    for date, values in rows:
        z_values = []
        for j, v in enumerate(values):
            if stds[j] == 0.0:
                z_values.append(0.0)  # constant column; avoid division by zero
            else:
                z_values.append((v - means[j]) / stds[j])
        result.append([date] + z_values)

    return result
