import math

def summarize_distribution(values, bins):
    vals = list(values)
    n = len(vals)

    if n == 0:
        raise ValueError("values must be non-empty")
    if bins <= 0:
        raise ValueError("bins must be a positive integer")

    # Mean
    mean = sum(vals) / n

    # Median
    sorted_vals = sorted(vals)
    mid = n // 2
    if n % 2 == 1:
        median = float(sorted_vals[mid])
    else:
        median = (sorted_vals[mid - 1] + sorted_vals[mid]) / 2

    # Mode: most frequent, ties broken by first appearance in original list
    counts = {}
    first_index = {}
    for i, v in enumerate(vals):
        if v not in counts:
            counts[v] = 0
            first_index[v] = i
        counts[v] += 1

    mode = min(counts, key=lambda v: (-counts[v], first_index[v]))

    # Population standard deviation
    variance = sum((x - mean) ** 2 for x in vals) / n
    std_dev = math.sqrt(variance)

    # Histogram
    mn = min(vals)
    mx = max(vals)
    histogram = [0] * bins

    if mn == mx:
        # All values are the maximum, so they go in the last bin
        histogram[-1] = n
    else:
        width = (mx - mn) / bins
        for x in vals:
            if x == mx:
                idx = bins - 1
            else:
                idx = int((x - mn) / width)
                if idx >= bins:
                    idx = bins - 1
                elif idx < 0:
                    idx = 0
            histogram[idx] += 1

    return {
        "mean": mean,
        "median": median,
        "mode": mode,
        "std_dev": std_dev,
        "histogram": histogram,
    }
