import math
import re
from collections import Counter

def _remove_bracketed(text: str) -> str:
    """Remove all balanced square-bracket spans, replacing them with spaces."""
    diff = [0] * (len(text) + 1)
    stack = []

    for i, ch in enumerate(text):
        if ch == '[':
            stack.append(i)
        elif ch == ']' and stack:
            start = stack.pop()
            diff[start] += 1
            diff[i + 1] -= 1

    out = []
    depth = 0
    for i, ch in enumerate(text):
        depth += diff[i]
        out.append(' ' if depth > 0 else ch)

    return ''.join(out)


def bracket_free_tfidf(texts):
    n = len(texts)

    # Remove bracketed text, lowercase, and extract words.
    docs = [re.findall(r'\w{2,}', _remove_bracketed(t).lower()) for t in texts]

    # Document frequency: number of strings containing each word.
    df = Counter()
    for words in docs:
        df.update(set(words))

    # Smoothed idf.
    idf = {word: math.log((1 + n) / (1 + df[word])) + 1 for word in df}

    result = []
    for words in docs:
        counts = Counter(words)

        # Raw TF multiplied by idf.
        scores = {word: counts[word] * idf[word] for word in sorted(counts)}

        # Unit Euclidean normalisation.
        norm = math.sqrt(sum(score * score for score in scores.values()))
        if norm > 0:
            scores = {word: score / norm for word, score in scores.items()}

        result.append(scores)

    return result
