def column_histogram(records, column_name):
    if not records or any(column_name not in row for row in records):
        raise ValueError(f"Column {column_name!r} does not exist")

    values = [row[column_name] for row in records]

    # If the column holds strings, replace them with their sorted distinct index.
    if all(isinstance(v, str) for v in values):
        distinct = sorted(set(values))
        rank = {val: i for i, val in enumerate(distinct)}
        values = [rank[v] for v in values]

    lo = min(values)
    hi = max(values)
    counts = [0] * 10

    if lo == hi:
        counts[9] = len(values)
        return counts

    # Exact integer arithmetic when possible; otherwise use floating-point bins.
    if all(isinstance(v, int) for v in values):
        span = hi - lo
        for v in values:
            if v == hi:
                idx = 9
            else:
                idx = (v - lo) * 10 // span
                if idx > 9:
                    idx = 9
            counts[idx] += 1
    else:
        width = (hi - lo) / 10.0
        for v in values:
            idx = int((v - lo) / width)
            if idx < 0:
                idx = 0
            elif idx > 9:
                idx = 9
            counts[idx] += 1

    return counts
