def course_grade_summary(records):
    totals = {}
    counts = {}
    passing = {}

    for student, course, grade in records:
        totals[course] = totals.get(course, 0) + grade
        counts[course] = counts.get(course, 0) + 1

        if grade >= 60:
            passing[course] = passing.get(course, 0) + 1

    return {
        course: (totals[course] / counts[course], passing.get(course, 0))
        for course in totals
    }
