import xml.etree.ElementTree as ET

def xml_to_dict(s):
    """Parse an XML string into nested Python dicts."""
    if not isinstance(s, str) or not s.strip():
        raise ValueError("input is empty or only whitespace")

    try:
        root = ET.fromstring(s)
    except ET.ParseError as exc:
        raise ValueError(f"invalid XML: {exc}") from exc

    def convert(el):
        children = list(el)
        attrs = {f"@{k}": v for k, v in el.attrib.items()}

        # Gather direct text: element text plus child tails
        if children:
            text_parts = []
            if el.text is not None:
                text_parts.append(el.text)
            for child in children:
                if child.tail is not None:
                    text_parts.append(child.tail)
            text = "".join(text_parts) if text_parts else None
        else:
            text = el.text

        # Leaf element with no attributes
        if not children and not attrs:
            return text if text is not None else None

        result = dict(attrs)

        if text is not None:
            result["#text"] = text

        for child in children:
            value = convert(child)
            tag = child.tag

            if tag in result:
                existing = result[tag]
                if not isinstance(existing, list):
                    result[tag] = [existing]
                result[tag].append(value)
            else:
                result[tag] = value

        return result

    return {root.tag: convert(root)}
```

Example:

```python
xml_to_dict('<book id="123">Python Guide</book>')
# {'book': {'@id': '123', '#text': 'Python Guide'}}
```

