from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.stack = []          # open <table> elements
        self.target = None       # the target table dict
        self.in_cell = False
        self.cell_parts = []

    def _current_table(self):
        return self.stack[-1] if self.stack else None

    def _finish_cell(self):
        text = "".join(self.cell_parts).strip()
        if self.target is not None and self.target["current_row"] is not None:
            self.target["current_row"].append(text)
        self.cell_parts = []
        self.in_cell = False

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "table":
            attrs_dict = {k.lower(): v for k, v in attrs}
            tbl = {"id": attrs_dict.get("id"), "rows": [], "current_row": None}
            self.stack.append(tbl)
            if self.target is None and tbl["id"] == self.table_id:
                self.target = tbl

        elif tag == "tr":
            tbl = self._current_table()
            if tbl is self.target:
                if self.in_cell:
                    self._finish_cell()
                if tbl["current_row"] is not None:
                    tbl["rows"].append(tbl["current_row"])
                tbl["current_row"] = []

        elif tag in ("td", "th"):
            tbl = self._current_table()
            if tbl is self.target and tbl["current_row"] is not None:
                if self.in_cell:
                    self._finish_cell()
                self.in_cell = True
                self.cell_parts = []

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag in ("td", "th"):
            tbl = self._current_table()
            if tbl is self.target and self.in_cell:
                self._finish_cell()

        elif tag == "tr":
            tbl = self._current_table()
            if tbl is self.target:
                if self.in_cell:
                    self._finish_cell()
                if tbl["current_row"] is not None:
                    tbl["rows"].append(tbl["current_row"])
                    tbl["current_row"] = None

        elif tag == "table":
            tbl = self._current_table()
            if tbl is self.target:
                if self.in_cell:
                    self._finish_cell()
                if tbl["current_row"] is not None:
                    tbl["rows"].append(tbl["current_row"])
                    tbl["current_row"] = None
            if self.stack:
                self.stack.pop()

    def handle_data(self, data):
        if self.in_cell:
            self.cell_parts.append(data)


def html_table_records(html, table_id):
    """
    Return a list of dicts for the rows in the table with the given id.
    The first row is treated as headers.
    """
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if parser.target is None:
        raise ValueError(f"No table with id {table_id!r}")

    rows = parser.target["rows"]
    if not rows:
        return []

    headers = rows[0]
    records = []

    for row in rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ""
        records.append(record)

    return records
```

