import html
import re
from html.parser import HTMLParser


class _TextExtractor(HTMLParser):
    """Collects text content while ignoring tags, attributes, and comments."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self._chunks = []

    def handle_data(self, data):
        self._chunks.append(data)

    def handle_entityref(self, name):
        # Keep entities raw for now; decode them all at once later.
        self._chunks.append(f"&{name};")

    def handle_charref(self, name):
        self._chunks.append(f"&#{name};")

    def get_text(self):
        return "".join(self._chunks)


def extract_emails_from_html(
    html,
    pattern=r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,7}\b'
):
    parser = _TextExtractor()
    parser.feed(html)
    parser.close()

    # Remove tags (by collecting only text nodes) and decode HTML entities.
    text = html.unescape(parser.get_text())

    # Return full regex matches in document order, keeping duplicates.
    return [match.group(0) for match in re.finditer(pattern, text)]
