import csv
import math
from io import StringIO

def _is_numeric(value):
    try:
        int(value)
        return True
    except (TypeError, ValueError):
        pass

    try:
        return math.isfinite(float(value))
    except (TypeError, ValueError):
        return False

def _to_number(value):
    try:
        return int(value)
    except ValueError:
        return float(value)

def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    headers = None
    raw_rows = []

    for text in csv_texts:
        rows = list(csv.reader(StringIO(text), skipinitialspace=True))
        if not rows:
            continue

        header = rows[0]
        if headers is None:
            headers = header

        col_index = {name: i for i, name in enumerate(header)}

        for row in rows[1:]:
            if not row:  # skip blank lines
                continue
            raw_rows.append([row[col_index[col]] for col in headers])

    if headers is None:
        return []

    numeric_columns = [
        all(_is_numeric(row[i]) for row in raw_rows)
        for i in range(len(headers))
    ]

    result = []
    for row in raw_rows:
        record = {}
        for i, col in enumerate(headers):
            if numeric_columns[i]:
                record[col] = _to_number(row[i])
            else:
                record[col] = row[i]
        result.append(record)

    return result
