import csv
import io
import math

def column_summary_stats(csv_text, column_name):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    if column_name not in header:
        raise ValueError(f"Column {column_name!r} not found in header")

    col_idx = header.index(column_name)
    values = []

    for row in reader:
        if len(row) > col_idx and row[col_idx].strip() != "":
            values.append(float(row[col_idx]))

    if not values:
        raise ValueError(f"Column {column_name!r} has no numeric values")

    n = len(values)
    mean = sum(values) / n

    sorted_values = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        median = float(sorted_values[mid])
    else:
        median = (sorted_values[mid - 1] + sorted_values[mid]) / 2.0

    variance = sum((x - mean) ** 2 for x in values) / n
    std_dev = math.sqrt(variance)

    return {"mean": mean, "median": median, "std_dev": std_dev}
