import math

def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = list(data.keys())
    if not columns:
        return {}

    # Apply the mapping to every value
    transformed = {}
    n = None
    for col in columns:
        vals = [mapping.get(v, v) for v in data[col]]
        if n is None:
            n = len(vals)
        elif len(vals) != n:
            raise ValueError("all columns must have the same length")
        transformed[col] = vals

    sums = {col: sum(transformed[col]) for col in columns}
    sum_sqs = {col: sum(v * v for v in transformed[col]) for col in columns}

    def pearson(a, b):
        sum_ab = sum(x * y for x, y in zip(transformed[a], transformed[b]))

        numerator = n * sum_ab - sums[a] * sums[b]
        den_a = n * sum_sqs[a] - sums[a] * sums[a]
        den_b = n * sum_sqs[b] - sums[b] * sums[b]

        if den_a <= 0 or den_b <= 0:
            return float("nan")

        return numerator / math.sqrt(den_a * den_b)

    result = {}
    for a in columns:
        result[a] = {}
        for b in columns:
            r = pearson(a, b)
            if a == b and not math.isnan(r):
                r = 1.0
            result[a][b] = r

    return result
