import csv
import io

def csv_mean_median(csv_text):
    if not csv_text:
        return (None, None)

    # Parse CSV rows, ignoring blank/whitespace-only lines.
    rows = [
        row for row in csv.reader(io.StringIO(csv_text))
        if row and any(cell.strip() for cell in row)
    ]

    if not rows:
        return (None, None)

    # First non-blank row is the header; skip it.
    data_rows = rows[1:]

    numbers = []
    for row in data_rows:
        value = row[0].strip()
        try:
            numbers.append(float(value))
        except ValueError:
            pass

    if not numbers:
        return (None, None)

    mean = sum(numbers) / len(numbers)

    ordered = sorted(numbers)
    n = len(ordered)
    if n % 2 == 1:
        median = float(ordered[n // 2])
    else:
        median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2.0

    return (mean, median)
