def box_blur(image, kernel_size):
    if (not isinstance(kernel_size, int) or isinstance(kernel_size, bool)
            or kernel_size <= 0 or kernel_size % 2 == 0):
        raise ValueError("kernel_size must be a positive odd integer")

    def reflect(i, n):
        """Map an index outside [0, n-1] by mirroring without repeating the border."""
        if n <= 1:
            return 0
        period = 2 * (n - 1)
        i %= period
        if i >= n:
            i = period - i
        return i

    if not image:
        return []

    h = len(image)
    w = len(image[0]) if h else 0
    if w == 0:
        return [[] for _ in image]

    channels = len(image[0][0])
    radius = kernel_size // 2
    area = kernel_size * kernel_size

    row_indices = [
        [reflect(r + dr, h) for dr in range(-radius, radius + 1)]
        for r in range(h)
    ]
    col_indices = [
        [reflect(c + dc, w) for dc in range(-radius, radius + 1)]
        for c in range(w)
    ]

    result = []
    for r in range(h):
        out_row = []
        for c in range(w):
            sums = [0.0] * channels
            for rr in row_indices[r]:
                row = image[rr]
                for cc in col_indices[c]:
                    pixel = row[cc]
                    for ch in range(channels):
                        sums[ch] += pixel[ch]
            out_row.append([total / area for total in sums])
        result.append(out_row)

    return result
