from collections import defaultdict
import math

def country_score_summary(records):
    if not records:
        raise ValueError("records must not be empty")

    required = ("Name", "Country", "Score")
    seen_names = set()
    kept = []

    for rec in records:
        if not isinstance(rec, dict):
            raise ValueError("each record must be a dict")

        for key in required:
            if key not in rec:
                raise ValueError(f"record is missing required key: {key!r}")

        name = rec["Name"]
        if name not in seen_names:
            seen_names.add(name)
            kept.append(rec)

    by_country = defaultdict(list)
    for rec in kept:
        by_country[rec["Country"]].append(float(rec["Score"]))

    def quantile(sorted_vals, p):
        n = len(sorted_vals)
        pos = (n - 1) * p
        lo = math.floor(pos)
        hi = math.ceil(pos)
        if lo == hi:
            return sorted_vals[lo]
        return sorted_vals[lo] + (pos - lo) * (sorted_vals[hi] - sorted_vals[lo])

    def five_number_summary(vals):
        s = sorted(vals)
        return [
            s[0],
            quantile(s, 0.25),
            quantile(s, 0.5),
            quantile(s, 0.75),
            s[-1]
        ]

    return {
        country: five_number_summary(scores)
        for country, scores in by_country.items()
    }
