def summarize_student_records(data):
    for key in ("Name", "Age", "Score"):
        if key not in data:
            raise ValueError(f"Missing required key: {key!r}")

    names = data["Name"]
    ages = data["Age"]
    scores = data["Score"]

    records = [[name, age, score] for name, age, score in zip(names, ages, scores)]
    records.sort(key=lambda r: (r[0], r[1]))  # stable sort keeps original order for equal (name, age)

    totals = {}
    counts = {}
    for name, score in zip(names, scores):
        totals[name] = totals.get(name, 0) + score
        counts[name] = counts.get(name, 0) + 1

    averages = {name: totals[name] / counts[name] for name in sorted(totals)}

    if not ages:
        most_common_age = None
    else:
        freq = {}
        for age in ages:
            freq[age] = freq.get(age, 0) + 1
        most_common_age = max(freq, key=freq.get)

    return records, averages, most_common_age
