import json
import math


def _is_numeric(value):
    """Return True if value is a finite JSON number (not bool)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _pearson(xs, ys):
    """Compute Pearson correlation between two equal-length numeric lists."""
    n = len(xs)
    if n == 0:
        return float("nan")

    mean_x = sum(xs) / n
    mean_y = sum(ys) / n

    cov = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    var_x = sum((x - mean_x) ** 2 for x in xs)
    var_y = sum((y - mean_y) ** 2 for y in ys)

    denom = math.sqrt(var_x * var_y)
    if denom == 0.0:
        return float("nan")   # correlation is undefined for constant columns

    return cov / denom


def numeric_correlation_from_json(json_text):
    """
    Parse a JSON object mapping column names to lists of values and return
    the pairwise Pearson correlation matrix for numeric columns only.
    """
    if not isinstance(json_text, str):
        raise ValueError("json_text must be a JSON string")

    try:
        data = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON must be an object")
    if not data:
        raise ValueError("Data is empty")

    numeric_cols = {
        name: values
        for name, values in data.items()
        if isinstance(values, list) and all(_is_numeric(v) for v in values)
    }

    if not numeric_cols:
        raise ValueError("Data is empty")

    lengths = {len(values) for values in numeric_cols.values()}
    if len(lengths) != 1:
        raise ValueError("Numeric columns must have equal lengths")
    if next(iter(lengths)) == 0:
        raise ValueError("Data is empty")

    names = list(numeric_cols.keys())
    result = {}

    for x_name in names:
        xs = numeric_cols[x_name]
        result[x_name] = {
            y_name: _pearson(xs, numeric_cols[y_name])
            for y_name in names
        }

    return result
