import math

def row_distance_matrix(rows):
    # Validate all elements are int or float
    for row in rows:
        for value in row:
            if not isinstance(value, (int, float)):
                raise TypeError(f"Element {value!r} is not an int or float")

    n = len(rows)
    matrix = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            distance = math.sqrt(
                sum((a - b) ** 2 for a, b in zip(rows[i], rows[j]))
            )
            matrix[i][j] = distance
            matrix[j][i] = distance

    return matrix
