import csv
import io
import math

def _cube_root(x):
    # Real cube root: works for negative numbers by restoring the sign.
    return math.copysign(abs(x) ** (1.0 / 3.0), x)

def csv_cube_roots(csv_text, columns):
    columns = list(columns)
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        header = []

    # Validate requested columns
    for col in columns:
        if col not in header:
            raise KeyError(col)

    data = {col: [] for col in header}

    for row in reader:
        if not row:
            continue
        if len(row) != len(header):
            raise ValueError(f"Expected {len(header)} fields per row, got {len(row)}")

        for col, raw in zip(header, row):
            try:
                value = float(raw)
            except (TypeError, ValueError):
                raise ValueError(f"Non-numeric value {raw!r} in column {col!r}") from None
            data[col].append(value)

    roots = {col: [_cube_root(v) for v in data[col]] for col in columns}

    return data, roots
