```python
def complete_row_histogram(data, bins):
    if bins <= 0:
        raise ValueError("bins must be a positive integer")

    cols = list(data.keys())
    cleaned = {col: [] for col in cols}

    # Keep only rows with no None in any column
    for row in zip(*data.values()):
        if any(v is None for v in row):
            continue
        vals = [float(v) for v in row]
        for col, v in zip(cols, vals):
            cleaned[col].append(v)

    # Pool all remaining values
    pooled = []
    for col in cols:
        pooled.extend(cleaned[col])

    if not pooled:
        return cleaned, None

    lo = min(pooled)
    hi = max(pooled)

    if lo == hi:
        return cleaned, None

    width = (hi - lo) / bins
    counts = [0] * bins

    for v in pooled:
        if v == hi:
            idx = bins - 1
        else:
            idx = int((v - lo) / width)
            if idx < 0:
                idx = 0
            elif idx >= bins:
                idx = bins - 1
        counts[idx] += 1

    return cleaned, counts
```

