def document_term_matrix(texts, stop_words):
    stop = {w.lower() for w in stop_words}
    tokenized_docs = []
    vocabulary = set()

    for text in texts:
        tokens = []
        current = []

        for ch in text.lower():
            if ch.isalnum():          # letters and digits only; "_" is not alnum
                current.append(ch)
            else:
                if current:
                    word = "".join(current)
                    if word not in stop:
                        tokens.append(word)
                        vocabulary.add(word)
                    current = []

        if current:
            word = "".join(current)
            if word not in stop:
                tokens.append(word)
                vocabulary.add(word)

        tokenized_docs.append(tokens)

    terms = sorted(vocabulary)
    term_index = {term: i for i, term in enumerate(terms)}

    counts = []
    for tokens in tokenized_docs:
        row = [0] * len(terms)
        for word in tokens:
            row[term_index[word]] += 1
        counts.append(row)

    return terms, counts
