def _solve_linear(A, b):
    """Solve A x = b using Gauss-Jordan elimination."""
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("Singular matrix in OLS normal equations")

        M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for j in range(n + 1):
            M[col][j] /= pivot_val

        for r in range(n):
            if r == col:
                continue
            factor = M[r][col]
            if factor != 0.0:
                for j in range(n + 1):
                    M[r][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]


def filtered_regression_coefficients(rows, height, weight, columns):
    target = columns[0]
    filter_col1 = columns[1]
    filter_col2 = columns[2]
    predictors = columns[1:]

    matched = [
        row for row in rows
        if row[filter_col1] > height and row[filter_col2] < weight
    ]

    if not matched:
        return None

    # Design matrix with intercept
    X = [[1.0] + [float(row[c]) for c in predictors] for row in matched]
    y = [float(row[target]) for row in matched]

    n = len(X)
    p = len(predictors) + 1

    # Normal equations: (X^T X) beta = X^T y
    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p

    for i in range(n):
        xi = X[i]
        yi = y[i]
        for a in range(p):
            Xty[a] += xi[a] * yi
            for b in range(p):
                XtX[a][b] += xi[a] * xi[b]

    beta = _solve_linear(XtX, Xty)

    result = {'const': float(beta[0])}
    for name, coef in zip(predictors, beta[1:]):
        result[name] = float(coef)

    return result
