import math
from collections import defaultdict

def _linear_quantile(sorted_vals, q):
    """Return the q-quantile using linear interpolation (numpy default)."""
    n = len(sorted_vals)
    if n == 1:
        return float(sorted_vals[0])

    pos = (n - 1) * q
    lower = math.floor(pos)
    upper = math.ceil(pos)

    if lower == upper:
        return float(sorted_vals[lower])

    weight = pos - lower
    return float(sorted_vals[lower] * (1 - weight) + sorted_vals[upper] * weight)


def fruit_sales_box_stats(records):
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = defaultdict(list)

    for fruit, _day, sales in records:
        sales_by_fruit[fruit].append(sales)

    result = {}

    for fruit, sales in sales_by_fruit.items():
        s = sorted(sales)
        result[fruit] = (
            float(s[0]),
            _linear_quantile(s, 0.25),
            _linear_quantile(s, 0.50),
            _linear_quantile(s, 0.75),
            float(s[-1]),
        )

    return result
