from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found_table = False
        self.done = False          # first table has been fully closed
        self.table_depth = 0
        self.headers = []
        self.rows = []             # list of {"cells": [...]}
        self.row_stack = []
        self.cell_stack = []       # each: {"type": "th"/"td", "parts": [], "row": row or None}

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        if self.table_depth == 0:
            if tag == "table":
                self.found_table = True
                self.table_depth = 1
            return

        if tag == "table":
            self.table_depth += 1
        elif tag == "tr":
            row = {"cells": []}
            self.row_stack.append(row)
            self.rows.append(row)
        elif tag in ("th", "td"):
            row = self.row_stack[-1] if self.row_stack else None
            self.cell_stack.append({"type": tag, "parts": [], "row": row})

    def handle_endtag(self, tag):
        if self.done:
            return
        if self.table_depth == 0:
            return

        if tag == "table":
            self.table_depth -= 1
            if self.table_depth == 0:
                self.done = True
        elif tag == "tr":
            if self.row_stack:
                self.row_stack.pop()
        elif tag in ("th", "td"):
            if self.cell_stack:
                cell = self.cell_stack.pop()
                text = "".join(cell["parts"]).strip()
                if cell["type"] == "th":
                    self.headers.append(text)
                elif cell["type"] == "td" and cell["row"] is not None:
                    cell["row"]["cells"].append(text)

    def handle_data(self, data):
        if self.done:
            return
        # Append to every open cell so ancestor cells include nested text,
        # matching "tags removed" behaviour.
        for cell in self.cell_stack:
            cell["parts"].append(data)


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()

    if not parser.found_table:
        raise ValueError("no <table> found")

    rows = [row["cells"] for row in parser.rows if row["cells"]]
    if not rows:
        raise ValueError("table has no data rows")

    return parser.headers, rows
```

