def standardize_filtered(data, age, weight):
    if 'Age' not in data or 'Weight' not in data:
        raise KeyError("Both 'Age' and 'Weight' columns are required")

    age_col = data['Age']
    weight_col = data['Weight']

    kept = [
        i for i in range(len(age_col))
        if age_col[i] < age and weight_col[i] > weight
    ]

    if not kept:
        return {col: [] for col in data}

    result = {}
    for col, values in data.items():
        kept_values = [values[i] for i in kept]
        n = len(kept_values)

        # Constant column -> all zeros
        if all(v == kept_values[0] for v in kept_values):
            result[col] = [0.0] * n
            continue

        mean = sum(kept_values) / n
        variance = sum((v - mean) ** 2 for v in kept_values) / n
        std = variance ** 0.5

        result[col] = [(v - mean) / std for v in kept_values]

    return result
