import csv
from io import StringIO

def grouped_column_means(csv_text, group_col, value_col):
    """
    Group CSV rows by group_col and return the mean of value_col per group.
    Blank value cells are ignored; non-numeric value cells raise ValueError.
    """
    reader = csv.DictReader(StringIO(csv_text), restval="")

    if reader.fieldnames is None:
        return {}
    if group_col not in reader.fieldnames or value_col not in reader.fieldnames:
        raise ValueError(f"Missing column: {group_col!r} or {value_col!r}")

    groups = {}

    for row in reader:
        group = row.get(group_col, "")
        label = "" if group is None else str(group)

        raw_value = row.get(value_col, "")
        if raw_value is None or raw_value.strip() == "":
            continue

        try:
            value = float(raw_value)
        except ValueError:
            raise ValueError(
                f"Non-numeric value in column {value_col!r}: {raw_value!r}"
            ) from None

        groups.setdefault(label, []).append(value)

    return {label: sum(values) / len(values) for label, values in groups.items()}
