def standardize_columns(data):
    result = {}

    for col, values in data.items():
        n = len(values)

        if n == 0:
            result[col] = ([], [0] * 20)
            continue

        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = variance ** 0.5

        if std == 0:
            standardized = [0.0] * n
        else:
            standardized = [(x - mean) / std for x in values]

        lo = min(standardized)
        hi = max(standardized)

        if hi == lo:
            bin_counts = [0] * 20
            bin_counts[-1] = n
        else:
            bin_counts = [0] * 20
            for v in standardized:
                idx = int((v - lo) / (hi - lo) * 20)
                if idx >= 20:
                    idx = 19
                bin_counts[idx] += 1

        result[col] = (standardized, bin_counts)

    return result
