from math import sqrt

def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    lengths = {len(col) for col in table.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    n = next(iter(lengths))
    if n == 0:
        raise ValueError("table is empty")

    def is_numeric_column(col):
        return all(
            isinstance(v, (int, float)) and not isinstance(v, bool)
            for v in col
        )

    numeric_cols = [
        name for name, col in table.items()
        if is_numeric_column(col)
    ]

    if not numeric_cols:
        raise ValueError("table has no numeric columns")

    numeric_set = set(numeric_cols)

    means = {}
    sums_of_squares = {}

    for name in numeric_cols:
        col = table[name]
        mean = sum(col) / n
        means[name] = mean
        sums_of_squares[name] = sum((x - mean) ** 2 for x in col)

    standardized = {}

    for name, col in table.items():
        if name in numeric_set:
            std = sqrt(sums_of_squares[name] / n)
            if std == 0:
                raise ValueError(
                    f"cannot standardize column {name!r}: zero variance"
                )
            standardized[name] = [
                (x - means[name]) / std for x in col
            ]
        else:
            standardized[name] = list(col)

    k = len(numeric_cols)
    corr = [[0.0] * k for _ in range(k)]

    for i in range(k):
        corr[i][i] = 1.0
        a = numeric_cols[i]

        for j in range(i + 1, k):
            b = numeric_cols[j]

            num = sum(
                (x - means[a]) * (y - means[b])
                for x, y in zip(table[a], table[b])
            )
            den = sqrt(sums_of_squares[a] * sums_of_squares[b])

            r = num / den
            corr[i][j] = r
            corr[j][i] = r

    return standardized, corr
