from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self.row_stack = []    # open <tr> elements: {'row': [...], 'depth': int}
        self.cell_stack = []   # open <td>/<th> elements: {'type', 'buffer', 'row', 'depth'}
        self.table_depth = 0

    def _current_row_at_depth(self, depth):
        for entry in reversed(self.row_stack):
            if entry['depth'] == depth:
                return entry['row']
        return None

    def _finalize_cell(self, cell):
        if cell['type'] == 'td' and cell['buffer'] is not None and cell['row'] is not None:
            cell['row'].append(''.join(cell['buffer']).strip())

    def _close_cell_at_depth(self, depth):
        for i in range(len(self.cell_stack) - 1, -1, -1):
            if self.cell_stack[i]['depth'] == depth:
                self._finalize_cell(self.cell_stack[i])
                del self.cell_stack[i]
                return

    def _close_cells_for_row(self, row, depth):
        for i in range(len(self.cell_stack) - 1, -1, -1):
            cell = self.cell_stack[i]
            if cell['row'] is row and cell['depth'] == depth:
                self._finalize_cell(cell)
                del self.cell_stack[i]

    def _close_row_at_depth(self, depth):
        for i in range(len(self.row_stack) - 1, -1, -1):
            if self.row_stack[i]['depth'] == depth:
                self._close_cells_for_row(self.row_stack[i]['row'], depth)
                del self.row_stack[i]
                return

    def _close_all_cells_at_depth(self, depth):
        kept = []
        for cell in self.cell_stack:
            if cell['depth'] == depth:
                self._finalize_cell(cell)
            else:
                kept.append(cell)
        self.cell_stack = kept

    def _close_all_rows_at_depth(self, depth):
        self.row_stack = [entry for entry in self.row_stack if entry['depth'] != depth]

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            self.table_depth += 1
        elif tag == 'tr':
            depth = self.table_depth
            self._close_cell_at_depth(depth)
