            self.rows.append(row)
            self.row_stack.append({'row': row, 'depth': depth})
        elif tag in ('td', 'th'):
            depth = self.table_depth
            self._close_cell_at_depth(depth)
            row = self._current_row_at_depth(depth)
            if row is not None:
                buffer = [] if tag == 'td' else None
