import json
from html.parser import HTMLParser

class _TitleParser(HTMLParser):
    def __init__(self):
        # convert_charrefs=True decodes HTML entities automatically
        super().__init__(convert_charrefs=True)
        self.title = None
        self._in_title = False
        self._parts = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "title" and self.title is None:
            self._in_title = True
            self._parts = []

    def handle_endtag(self, tag):
        if tag.lower() == "title" and self._in_title:
            self.title = "".join(self._parts)
            self._in_title = False

    def handle_data(self, data):
        if self._in_title:
            self._parts.append(data)


def extract_title_json(html):
    parser = _TitleParser()
    parser.feed(html)
    parser.close()
    return json.dumps({"title": parser.title}, ensure_ascii=False)
```

